const lines = $input.item.json.lines || $input.item.json.pages;
let model = 0;

if ($input.item.json.type === "text" && lines[0] === "Extrato por período") {
  model = 1;
} else
if ($input.item.json.type === "text" && lines[0] !== "Extrato por período") {
  model = 2;
} else
if ($input.item.json.type === "ocr") {
  model = 3;
}

return { model, lines };

const bank = "CAIXA ECONOMICA FEDERAL";
const linhas = $input.item.json.lines;

const ignorarDescricoes = new Set([
  "SALDO DIA",
  "CORRECAO MONETARIA",
  "CREDITO JUROS"
]);

// ==================================================
// CLIENTE
// ==================================================

const clientName = linhas[0];


// ==================================================
// REGEX
// ==================================================

const regexData =
  /^\d{2}\/\d{2}\/\d{4}$/;

const regexDataEfetiva =
  /^\d{2}\/\d{2}\s+\d{2}:\d{2}$/;

const regexDocumento =
  /^\d+$/;


// Procura o VALOR + SALDO em qualquer lugar da linha.
//
// Exemplos:
//
// R$ 50,00 R$ 59,31 C
// - R$ 50,00 R$ 9,31 C
// 311026 DEPOSITO DINH LOTERICO R$ 50,00 R$ 59,31 C
//
const regexValorSaldo =
  /(-\s*)?R\$\s*([\d.]+,\d{2})\s+R\$\s*([\d.]+,\d{2})\s+([CD])/;


// ==================================================
// EXTRAIR VALOR
// ==================================================

function extrairValor(linha) {

  const match = linha.match(regexValorSaldo);

  if (!match) {
    return null;
  }

  const [
    trecho,
    sinal,
    valor,
    saldo,
    tipoSaldo
  ] = match;

  return {
    trecho,
    valor,
    saldo,
    tipoSaldo,
    tipoTransacao: sinal
      ? "SAIDA"
      : "ENTRADA"
  };
}


// ==================================================
// TRANSAÇÕES
// ==================================================

const transacoes = [];

let i = 0;


while (i < linhas.length) {

  const linha = linhas[i];


  // =================================================
  // IGNORAR LINHAS QUE NÃO SÃO DATA
  // =================================================

  if (!regexData.test(linha)) {
    i++;
    continue;
  }


  const dataTransacao = linha;


  // =================================================
  // SALDO DIA
  //
  // Exemplo:
  //
  // 02/02/2026 SALDO DIA R$ 49,31 C
  // =================================================

  if (
    i + 1 < linhas.length &&
    linhas[i + 1] === "SALDO DIA"
  ) {

    i += 2;
    continue;
  }


  // =================================================
  // DATA EFETIVA
  // =================================================

  let pos = i + 1;

  if (
    pos >= linhas.length ||
    !regexDataEfetiva.test(linhas[pos])
  ) {
    i++;
    continue;
  }

  pos++;


  // =================================================
  // DOCUMENTO / DESCRIÇÃO
  // =================================================

  let documento = null;
  let descricaoLinhas = [];


  // =================================================
  // CASO 1
  //
  // Documento sozinho:
  //
  // 311906
  // DEB PIX CHAVE
  // BRUNO MOREIRA...
  // E003...
  // - R$ 50,00 R$ 9,31 C
  // =================================================

  if (
    pos < linhas.length &&
    regexDocumento.test(linhas[pos])
  ) {

    documento = linhas[pos];

    pos++;

    // Tudo até encontrar o valor será descrição
    while (pos < linhas.length) {

      const linhaDescricao = linhas[pos];

      const valorEncontrado =
        extrairValor(linhaDescricao);

      if (valorEncontrado) {
        break;
      }

      // Se encontrou outra data, interrompe
      if (regexData.test(linhaDescricao)) {
        break;
      }

      descricaoLinhas.push(linhaDescricao);

      pos++;
    }

  }

  // =================================================
  // CASO 2
  //
  // Documento + descrição + valor na mesma linha:
  //
  // 311026 DEPOSITO DINH LOTERICO R$ 50,00 R$ 59,31 C
  // =================================================

  else {

    if (pos >= linhas.length) {
      i++;
      continue;
    }

    const linhaTransacao = linhas[pos];

    const valorEncontrado =
      extrairValor(linhaTransacao);

    if (!valorEncontrado) {
      i++;
      continue;
    }


    // Pega tudo que está antes do primeiro R$
    const indiceValor =
      linhaTransacao.search(/-?\s*R\$/);

    if (indiceValor === -1) {
      i++;
      continue;
    }

    const parteInicial =
      linhaTransacao
        .substring(0, indiceValor)
        .trim();


    // Documento + descrição
    const match =
      parteInicial.match(/^(\d+)\s+(.+)$/);

    if (!match) {
      i++;
      continue;
    }

    documento = match[1];

    descricaoLinhas.push(match[2]);


    // =================================================
    // CRIAR TRANSAÇÃO
    // =================================================

    const descricao =
      descricaoLinhas
        .join(" ")
        .trim();

    if (
      !ignorarDescricoes.has(
        descricao.toUpperCase()
      )
    ) {

      transacoes.push({
        data: dataTransacao,
        documento,
        descricao,
        valor: valorEncontrado.valor,
        tipoTransacao: valorEncontrado.tipoTransacao
      });
    }


    // Já processamos a linha inteira
    i = pos + 1;

    continue;
  }


  // =================================================
  // CASO DOCUMENTO SEPARADO
  // =================================================

  if (
    pos >= linhas.length
  ) {
    i++;
    continue;
  }


  const linhaValor = linhas[pos];

  const valorEncontrado =
    extrairValor(linhaValor);


  if (!valorEncontrado) {
    i++;
    continue;
  }


  const descricao =
    descricaoLinhas
      .join(" ")
      .trim();


  // =================================================
  // IGNORAR DESCRIÇÕES
  // =================================================

  if (
    !ignorarDescricoes.has(
      descricao.toUpperCase()
    )
  ) {

    transacoes.push({
      data: dataTransacao,
      documento,
      descricao,
      valor: valorEncontrado.valor,
      tipoTransacao: valorEncontrado.tipoTransacao
    });

  }


  // =================================================
  // CONTINUAR
  // =================================================

  i = pos + 1;
}


// ==================================================
// RESULTADO
// ==================================================

return {
  bank,
  clientName,
  count: transacoes.length,
  transacoes
};

const bank = "CAIXA ECONOMICA FEDERAL";
const linhas = $input.item.json.lines;
const regex = /^(\d{2}\/\d{2}\/\d{4})\s+(\d+)\s+(.+?)\s+([\d.,]+)\s+([CD])\s+[\d.,]+\s+[CD]$/;
const ignorarDescricoes = new Set([
    "SALDO DIA", "CORRECAO MONETARIA", "CREDITO JUROS"
]);

// Pegar Nome do Cliente
let clientName = linhas[3];

// Pegar as Transações
const transacoes = linhas.map(linha => {

  const match = linha.match(regex);

  if (!match) return null;

  const [, data, documento, descricao, valor, tipoTransacao] = match;

  if (ignorarDescricoes.has(descricao.toUpperCase())) {
    return null;
  }

  return {
    data,
    documento,
    descricao,
    valor,
    tipoTransacao: tipoTransacao === 'C' ? 'ENTRADA' : 'SAIDA'
  };

}).filter(Boolean);

let count = transacoes.length;

return { bank, clientName, count, transacoes };

const data = $input.item.json.lines;
let table = [];

const lines = data[0].markdown.split(/\r?\n/).map(linha => linha.trim()).filter(linha => linha !== "");

const clientMatch = lines[3].match(
  /Cliente\s*([^\r\n]+)/i
);

const clientName = clientMatch
  ? clientMatch[1].trim()
  : null;

data.forEach(d => {
  d.tables.forEach(dt => {
    table.push(dt.content);
  });
});

return { clientName, table };

const bank = "CAIXA ECONOMICA FEDERAL";
let clientName = $input.first().json.clientName;

const result = [];

// Função para limpar HTML
function stripHtml(html) {
  return html
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .trim();
}

// Extrai o primeiro lançamento monetário encontrado
// Ex:
// "60,00 C" -> { value: 60, type: "ENTRADA" }
// "272,58 D 15.134,27 C" -> { value: 272.58, type: "SAIDA" }
function parseTransactionValue(text) {
  const match = text.match(
    /(\d{1,3}(?:\.\d{3})*,\d{2})\s*([CD])/
  );

  if (!match) {
    return {
      value: null,
      type: null
    };
  }

  const value = Number(
    match[1]
      .replace(/\./g, '')
      .replace(',', '.')
  );

  return {
    value,
    type: match[2] === 'C' ? 'Entrada' : 'Saída'
  };
}

// Tabelas retornadas pela Mistral
const tables = $input.first().json.table || [];

for (const table of tables) {

  const rows = table.match(/<tr[\s\S]*?<\/tr>/gi) || [];

  for (const row of rows) {

    const cells = [...row.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)]
      .map(match => stripHtml(match[1]));

    if (cells.length < 5) {
      continue;
    }

    const dataHora = cells[0];
    const historico = cells[2] || '';
    const favorecido = cells[3] || '';

    // Ignorar linhas que não são lançamentos
    if (
      !/\d{2}\/\d{2}\/\d{4}/.test(dataHora) ||
      historico === 'SALDO DIA' ||
      historico === 'SALDO ANTERIOR' ||
      historico === 'CORRECAO MONETARIA' ||
      historico === 'CREDITO JUROS'
    ) {
      continue;
    }

    // Procura a primeira célula que contenha um valor monetário
    const valorTexto = cells.find(cell =>
      /(\d{1,3}(?:\.\d{3})*,\d{2})\s*[CD]/.test(cell)
    );

    if (!valorTexto) {
      continue;
    }

    const transaction = parseTransactionValue(valorTexto);

    result.push({
      data: dataHora.replace(' - ', ' '),
      documento: "",
      descricao: `${historico}${favorecido ? ' ' + favorecido : ''}`.trim(),
      valor: transaction.value,
      tipoTransacao: transaction.type
    });
  }
}

return {
  bank,
  clientName,
  count: result.length,
  transacoes: result
};
